package core

import (
	"sort"

	"github.com/jokruger/kavun/core/member"
	"github.com/jokruger/kavun/errs"
)

// dict's members: one function per member, each declared by the //kavun:member directive in its doc comment. The table,
// dictMethods, and the member entries of docs/reference/types/dict.md (alphabetical, so the order here is free) are
// generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Render the value per the [format mini-language](../../format_mini_language.md).
//
// ```go
// dict({a: 1}).format()          // the render: dict({"a": 1})
// ```
//
//kavun:member format pure ([spec]) -> string
func dictFormat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return FormatWithSpec(v, id, args)
}

// Report truthiness, which is non-emptiness: `!!x` ⟺ `x != dict()`.
//
// ```go
// dict({a: 1}).is_true()         // => true — a dict is truthy iff non-empty
// dict().is_true()               // => false
// !!dict()                       // => false — same test
// ```
//
//kavun:member is_true pure () -> bool
func dictIsTrue(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	t, err := ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(t), nil
}

// Answer an independent deep copy.
//
// ```go
// d = dict({a: [1, 2]})
// c = d.copy()                   // deep: c["a"] is an independent array
// ```
//
//kavun:member copy pure () -> dict
func dictCopy(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return dictTypeCopy(v, true)
}

// Answer a copy with a fresh top level, nested values still shared.
//
// ```go
// d = dict({a: [1, 2]})
// s = d.copy_shallow()           // one level: s is a new map, s["a"] is d's array
// ```
//
//kavun:member copy_shallow pure () -> dict
func dictCopyShallow(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return dictTypeCopy(v, false)
}

// Mark the header you hold immutable without detaching; reassign to see it (`d = d.freeze_shallow()`).
//
// ```go
// g = dict({a: [1]}).freeze_shallow()
// g["b"] = 2                     // Error: not_assignable — the map itself is frozen
// g["a"].push_in_place(2)        // fine — one level only, the inner array stayed mutable
// ```
//
//kavun:member freeze_shallow pure () -> dict
func dictFreezeShallow(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return v.ToImmutable()
}

// Answer a deep-immutable *copy*; the source and its aliases are untouched.
//
// ```go
// f = dict({a: [1]}).freeze()    // deep: the dict and its elements are immutable
// f["a"].push_in_place(2)        // Error: not_mutable — the inner array froze too
// ```
//
//kavun:member freeze pure () -> dict
func dictFreeze(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return v.Freeze()
}

// Answer a new, independent, mutable **shallow** copy, exactly `dict(d)` / `d.copy_shallow()`.
//
// `d.dict()` converts from a dict to a dict, and like every conversion it **constructs**: an independent
// `dict` with the same entries, exactly `dict(d)` / `d.copy_shallow()`. It is equal to the receiver but is not
// the receiver, so a write through it never reaches `d`. Shared storage is `record_view()`'s job, never a
// conversion's:
//
// ```go
// d = dict({a: 1})
// e = d.dict()
// e == d                 // => true — equal entries
// e["b"] = 2
// d                      // => dict({"a": 1}) — untouched
// ```
//
//kavun:member dict pure ([default]) -> dict
func dictDict(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	c, err := dictTypeCopy(v, false)
	if err != nil {
		return Undefined, err
	}
	return ConvMember(id.String(), dictTypeName, args, true, c)
}

// Answer an independent record with the same entries.
//
// `d.record()` answers an independent record with the same entries; `d.record_view()` answers a record **sharing
// the dict's map** — the performance opt-in when you want record-style field access over live dict data:
//
// ```go
// d = dict({a: 1})
// r = d.record_view()
// d["b"] = 2
// r.b                    // => 2 — the view sees the write
// ```
//
// The `default` is taken for interface uniformity — every conversion carries it — and is never used: the
// conversion is total.
//
//kavun:member record pure ([default]) -> record
func dictRecord(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return ConvMember(id.String(), dictTypeName, args, true, DictToRecord(v, false))
}

// Answer a record sharing the dict's map; see [`record`](#record).
//
//kavun:member record_view pure () -> record
func dictRecordView(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return DictToRecord(v, true), nil
}

// Answer the entries as a new array of `[key, value]` pairs, key-sorted.
//
// `d.array()` materialises the entries, key-sorted — each entry exactly a 2-element `[key, value]` array. It is
// the inverse of the entries constructor, so the two round-trip up to ordering:
//
// ```go
// dict({b: 2, a: 1}).array()             // => [["a", 1], ["b", 2]]
// d = dict({b: 2, a: 1})
// d.array().dict() == d                  // => true
// ```
//
//kavun:member array pure ([default]) -> array
func dictArray(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Dict)(v.Ptr)
	return ConvMember(id.String(), dictTypeName, args, true, NewArrayValue(MapToSortedEntries(o.Elements), false))
}

// Build a `time` from the named components; an unknown key raises.
//
// `d.time()` and `d.range()` are the component-form constructors: the dict supplies named components, and an
// unknown key raises (`invalid_value`) rather than being ignored:
//
// ```go
// dict({year: 2026, month: 8, day: 29}).time()   // => time("2026-08-29T00:00:00Z")
// dict({start: 1, stop: 5}).range()              // => range(1, 5)
// dict({start: 1, xx: 5}).range()                // Error: invalid_value — unknown component "xx"
// ```
//
//kavun:member time pure ([default]) -> time
func dictTime(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	// a components map is a conversion (it has a receiver), unlike the
	// positional construction forms; time(d.components-shaped dict) agrees
	o := (*Dict)(v.Ptr)
	if len(args) > 1 {
		return Undefined, ErrArgCount
	}
	t, err := TimeFromComponents(o.Elements)
	if err != nil {
		if len(args) == 1 {
			return args[0], nil
		}
		return Undefined, err
	}
	return ConvMember(id.String(), dictTypeName, args, true, NewTimeValue(t))
}

// Build a `date` from the named components `year`, `month` and `day`; an unknown key raises; see [`time`](#time).
//
//kavun:member date pure ([default]) -> date
func dictDate(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Dict)(v.Ptr)
	if len(args) > 1 {
		return Undefined, ErrArgCount
	}
	d, err := DateFromComponents(o.Elements)
	if err != nil {
		if len(args) == 1 {
			return args[0], nil
		}
		return Undefined, err
	}
	return ConvMember(id.String(), dictTypeName, args, true, DateValue(d))
}

// Build a `range` from the named components `start`, `stop` and `step`; an unknown key raises; see [`time`](#time).
//
//kavun:member range pure ([default]) -> range
func dictRange(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Dict)(v.Ptr)
	if len(args) > 1 {
		return Undefined, ErrArgCount
	}
	r, err := RangeFromComponents(o.Elements)
	if err != nil {
		if len(args) == 1 {
			return args[0], nil
		}
		return Undefined, err
	}
	return ConvMember(id.String(), dictTypeName, args, true, r)
}

// Report whether some key matches a key, a member of a set of keys or a predicate.
//
// All of the search members match **keys** — the value axis is `d.values()`'s job. They share three readings: a
// single value (converted to a key the way the index operator converts), a variadic set of them ("∈ the set"), or a
// predicate (it gets the key, or `(key, value)` when it does not accept one argument — [callbacks](#callbacks)). No
// argument raises; mixing a function into a set raises:
//
// ```go
// d = dict({a: 1, b: 2})
// d.contains("a")                              // => true
// d.contains(1)                                // => false — the key "1" is absent (never matches values)
// d.contains("x", "a")                         // => true — any of the set
// d.contains(func(k) { return k.len() > 1 })   // => false
// d.contains()                                 // Error: wrong_num_arguments
// d.contains(dict({a: 1}))                     // Error: not_implemented — the submap reading is reserved
// ```
//
//kavun:member contains pure (x, ...more) -> bool
func dictContains(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	m, err := dictReadMatchArgs(vm, "contains", args)
	if err != nil {
		return Undefined, err
	}
	o := (*Dict)(v.Ptr)
	for _, k := range o.sortedKeys() {
		hit, err := m.matches(k, o.Elements[k])
		if err != nil {
			return Undefined, err
		}
		if hit {
			return True, nil
		}
	}
	return False, nil
}

// Count the keys that match a key, a set of keys or a predicate.
//
// A function argument gets the key, or `(key, value)` when it does not accept one argument ([callbacks](#callbacks)).
//
// ```go
// d = dict({a: 1, b: 2})
// d.count("a", "b", "z")                       // => 2
// d.count(func(k, v) { return v > 1 })         // => 1
// ```
//
//kavun:member count pure (x, ...more) -> int
func dictCount(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	m, err := dictReadMatchArgs(vm, "count", args)
	if err != nil {
		return Undefined, err
	}
	o := (*Dict)(v.Ptr)
	n := int64(0)
	for _, k := range o.sortedKeys() {
		hit, err := m.matches(k, o.Elements[k])
		if err != nil {
			return Undefined, err
		}
		if hit {
			n++
		}
	}
	return IntValue(n), nil
}

// Keep only the entries whose key is in the key set, or which match a predicate; see [`remove`](#remove).
//
// A function argument gets the key, or `(key, value)` when it does not accept one argument ([callbacks](#callbacks)).
//
//kavun:member keep pure (x, ...more) -> dict
func dictKeep(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := dictKept(vm, "keep", v, args)
	if err != nil {
		return Undefined, err
	}
	return NewDictValue(out, false), nil
}

// In-place twin of `keep`.
//
//kavun:member keep_in_place impure (x, ...more) -> dict
func dictKeepInPlace(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	const name = "keep_in_place"
	if v.Immutable {
		return Undefined, errs.NewNotMutableError(name, v.TypeName())
	}
	out, err := dictKept(vm, name, v, args)
	if err != nil {
		return Undefined, err
	}
	(*Dict)(v.Ptr).Set(out)
	return v, nil
}

// Remove the entries whose key is in the key set, or which match a predicate.
//
// Both act on whole entries and take either a **key set** (variadic strings — or values convertible to keys) or a
// **predicate**, and the names say which way each one goes: `remove` drops the matching entries, `keep` answers
// exactly them. A missing key is a silent no-op. A predicate gets the key, or `(key, value)` when it does not accept
// one argument ([callbacks](#callbacks)). Neither has a no-argument form — a map's keys are identities, never filler, so there is no
// blank set to read against:
//
// ```go
// dict({a: 1, b: 2}).remove("a")                   // => dict({"b": 2})
// dict({a: 1, b: 2, c: 3}).remove("a", "c")        // => dict({"b": 2})
// dict({a: 1}).remove("zz")                        // => dict({"a": 1}) — absent, no-op
// dict({aa: 1, b: 2}).remove(func(k) { return k.len() > 1 })     // => dict({"b": 2})
// dict({a: 1, b: 2}).remove(func(k, v) { return v > 1 })         // => dict({"a": 1})
//
// dict({a: 1, b: 2, c: 3}).keep("a", "c")        // => dict({"a": 1, "c": 3})
// dict({a: 1, b: 2}).keep(func(k, v) { return v > 1 })         // => dict({"b": 2})
//
// dict({a: 1}).keep()      // Error: wrong_num_arguments — a map has no blank reading
// dict({a: 1}).remove()      // Error: wrong_num_arguments
// ```
//
// A match set is homogeneous: mixing a function with keys in one call raises. The `_in_place` twins mutate the
// receiver and return it; on a frozen dict they raise `not_mutable`.
//
//kavun:member remove pure (x, ...more) -> dict
func dictRemove(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	out, err := dictRemaining(vm, "remove", v, args)
	if err != nil {
		return Undefined, err
	}
	return NewDictValue(out, false), nil
}

// In-place twin of `remove`.
//
//kavun:member remove_in_place impure (x, ...more) -> dict
func dictRemoveInPlace(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	const name = "remove_in_place"
	if v.Immutable {
		return Undefined, errs.NewNotMutableError(name, v.TypeName())
	}
	out, err := dictRemaining(vm, name, v, args)
	if err != nil {
		return Undefined, err
	}
	(*Dict)(v.Ptr).Set(out)
	return v, nil
}

// Report whether some entry matches a key, a set of keys or a predicate.
//
// A function argument gets the key, or `(key, value)` when it does not accept one argument ([callbacks](#callbacks)).
//
// ```go
// d = dict({a: 1, b: 2})
// d.any("a")                                   // => true
// d.all(func(k, v) { return v > 0 })           // => true
// ```
//
//kavun:member any pure (x, ...more) -> bool
func dictAny(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	m, err := dictReadMatchArgs(vm, "any", args)
	if err != nil {
		return Undefined, err
	}
	o := (*Dict)(v.Ptr)
	for _, k := range o.sortedKeys() {
		hit, err := m.matches(k, o.Elements[k])
		if err != nil {
			return Undefined, err
		}
		if hit {
			return True, nil
		}
	}
	return False, nil
}

// Report whether every entry matches a key, a set of keys or a predicate; see [`any`](#any).
//
// A function argument gets the key, or `(key, value)` when it does not accept one argument ([callbacks](#callbacks)).
//
//kavun:member all pure (x, ...more) -> bool
func dictAll(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	// True on an empty dict.
	m, err := dictReadMatchArgs(vm, "all", args)
	if err != nil {
		return Undefined, err
	}
	o := (*Dict)(v.Ptr)
	for _, k := range o.sortedKeys() {
		hit, err := m.matches(k, o.Elements[k])
		if err != nil {
			return Undefined, err
		}
		if !hit {
			return False, nil
		}
	}
	return True, nil
}

// Answer a new dict with the same keys, each value replaced by the callback's result.
//
// `map` transforms the **attachment** with the keys fixed: the callback's result becomes the new value for that key,
// and the answer is a new `dict` of the same keys. The callback gets the key, or `(key, value)` when it does not accept
// one argument ([callbacks](#callbacks)); anything else raises. Re-keying is a different operation — and one that can
// collide — so `map` never touches the key axis (build a new dict via `reduce` or a loop if you need it):
//
// ```go
// dict({a: 1, b: 2}).map(func(k, v) { return v * 10 })   // => dict({"a": 10, "b": 20})
// dict({a: 1, b: 2}).map(func(k) { return k + "!" })     // => dict({"a": "a!", "b": "b!"})
// ```
//
// There is no `map_in_place` — `map`'s result is a new dict by contract.
//
//kavun:member map pure (fn) -> dict
func dictMap(vm VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Dict)(v.Ptr)
	cb, err := readElemCallback(vm, id.String(), args)
	if err != nil {
		return Undefined, err
	}
	mapped := make(map[string]Value, len(o.Elements))
	for _, k := range o.sortedKeys() {
		res, err := cb.CallEntry(NewStringValue(k), o.Elements[k])
		if err != nil {
			return Undefined, err
		}
		mapped[k] = res
	}
	return NewDictValue(mapped, false), nil
}

// Fold the entries, in sorted key order, into an accumulator that starts at `init`.
//
// `reduce(init, fn)` folds over the entries in **sorted key order** (deterministic by construction). The callback
// gets `(acc, key)`, or `(acc, key, value)` when it does not accept two arguments ([callbacks](#callbacks)):
//
// ```go
// dict({b: 1, a: 1}).reduce("", func(acc, k) { return acc + k })              // => "ab"
// dict({b: 2, a: 1, c: 3}).reduce(0, func(acc, k, v) { return acc*10 + v })   // => 123
// ```
//
//kavun:member reduce pure (init, fn) -> value
func dictReduce(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	o := (*Dict)(v.Ptr)
	acc, cb, err := readReduceArgs(vm, args)
	if err != nil {
		return Undefined, err
	}
	for _, k := range o.sortedKeys() {
		acc, err = cb.CallEntry(acc, NewStringValue(k), o.Elements[k])
		if err != nil {
			return Undefined, err
		}
	}
	return acc, nil
}

// Merge the entries of the `dict` and `record` arguments into a new dict, in argument order, last one winning.
//
// `merge` is the whole add side. It is variadic over `dict` **and** `record` arguments; entries are applied in
// argument order, last one wins; no arguments is a no-op; any non-map argument raises `invalid_argument_type`:
//
// ```go
// dict({a: 1}).merge(dict({b: 2}), {a: 9})       // => dict({"a": 9, "b": 2})
// dict({a: 1}).merge(dict({a: 2}), dict({a: 3})) // => dict({"a": 3}) — argument order, last wins
// dict({a: 1}).merge()                           // => dict({"a": 1})
// dict({a: 1}).merge([1, 2])                     // Error: invalid_argument_type — dict or record only
//
// m = dict({a: 1})
// m.merge_in_place(dict({b: 2}))     // returns m itself; m is now dict({"a": 1, "b": 2})
// dict({a: 1}).freeze().merge_in_place(dict({b: 2}))   // Error: not_mutable
// ```
//
// There is deliberately **no single-entry add member** (`set`, `put`, …). The two spellings are:
//
// ```go
// d := dict()
// k := "a"
// v := 1
// d[k] = v                     // the mutating statement
// d.merge(dict([[k, v]]))      // non-mutating, via the entries constructor
// ```
//
//kavun:member merge pure (...maps) -> dict
func dictMerge(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return dictTypeMerge(v, args, false)
}

// In-place twin of `merge`.
//
//kavun:member merge_in_place impure (...maps) -> dict
func dictMergeInPlace(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return dictTypeMerge(v, args, true)
}

// Report whether the dict has no entries.
//
// ```go
// d = dict({b: 2, a: 1, c: 3})
// d.is_empty()     // => false
// ```
//
//kavun:member is_empty pure () -> bool
func dictIsEmpty(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Dict)(v.Ptr)
	return BoolValue(len(o.Elements) == 0), nil
}

// Answer the number of entries.
//
// ```go
// d = dict({b: 2, a: 1, c: 3})
// d.len()          // => 3
// ```
//
//kavun:member len pure () -> int
func dictLen(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	o := (*Dict)(v.Ptr)
	return IntValue(int64(len(o.Elements))), nil
}

// Answer the keys as a new array, sorted.
//
// ```go
// d = dict({b: 2, a: 1, c: 3})
// d.keys()         // => ["a", "b", "c"] — a fresh array, sorted
// ```
//
// `keys()`/`values()` answer new arrays; mutating them does not touch the dict. They are also the spelling for
// every value-axis or whole-collection question the dict deliberately does not answer itself:
//
// ```go
// dict({a: 1, b: 2}).values().sum()        // => 3
// dict({z: 1, a: 2}).keys().min()          // => "a"
// dict({a: 1}).values().contains(1)        // => true — "does any entry hold this value?"
// ```
//
//kavun:member keys pure () -> array
func dictKeys(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return dictFnKeys(v)
}

// Answer the values as a new array, in `keys()` order; see [`keys`](#keys).
//
// ```go
// d = dict({b: 2, a: 1, c: 3})
// d.values()       // => [1, 2, 3] — a fresh array, in keys() order
// ```
//
//kavun:member values pure () -> array
func dictValues(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return dictFnValues(v)
}

// Call the callback on every entry, in sorted key order — always a **full pass**, its return value ignored — and
// return the receiver.
//
// The callback gets the key, or `(key, value)` when it does not accept one argument ([callbacks](#callbacks)).
//
// `for_each(fn)` makes one full pass in sorted key order — the callback's return value is ignored (early exit is
// `break`'s job, in a `for` loop) — and returns the receiver. Being the side-effecting member, its order is the
// most visible of all: a `for_each` that prints or accumulates gives the same result on every run.
//
// ```go
// d = dict({a: 1})
// d.for_each(func(k, v) {})         // visits every entry, keys ascending; answers d itself
//
// o = []
// dict({zebra: 1, apple: 2}).for_each(func(k) { o.append_in_place(k) })
// o                                  // => ["apple", "zebra"]
// ```
//
//kavun:member for_each pure (fn) -> dict
func dictForEach(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	cb, err := readElemCallback(vm, "for_each", args)
	if err != nil {
		return Undefined, err
	}

	o := (*Dict)(v.Ptr)
	for _, k := range o.sortedKeys() {
		if _, err := cb.CallEntry(NewStringValue(k), o.Elements[k]); err != nil {
			return Undefined, err
		}
	}
	return v, nil
}

// Answer the first key, in sorted order, that matches a key or a predicate, or `undefined` (the default when given)
// on a miss.
//
// A function argument gets the key, or `(key, value)` when it does not accept one argument ([callbacks](#callbacks)).
//
// `index(x[, default])` answers a **key** — the map's locator is its element, not a position. It visits keys in
// sorted order, so a predicate's answer is deterministic; a miss answers `undefined`, or the trailing default:
//
// ```go
// dict({apple: 1, pear: 2}).index(func(k, v) { return v == 2 })   // => "pear"
// dict({z: 1, b: 1, a: 1}).index(func(k, v) { return v == 1 })    // => "a" — sorted visit
// dict({a: 1}).index("z")                                         // => undefined
// dict({a: 1}).index("z", "fallback")                             // => "fallback"
// ```
//
// There is no `index_last` — with no defined order, "last" does not exist on a dict.
//
//kavun:member index pure (x[, default]) -> string
func dictIndex(vm VM, v Value, _ member.ID, args []Value) (Value, error) {
	if len(args) > 2 {
		return Undefined, ErrArgCount
	}
	o := (*Dict)(v.Ptr)
	needle := args[0]
	dflt := args[1:]
	miss := func() (Value, error) {
		if len(dflt) == 1 {
			return dflt[0], nil
		}
		return Undefined, nil
	}

	keys := make([]string, 0, len(o.Elements))
	for k := range o.Elements {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	if needle.IsCallable() {
		cb, err := newElemCallback(vm, "index", needle)
		if err != nil {
			return Undefined, err
		}
		for _, k := range keys {
			res, err := cb.CallEntry(NewStringValue(k), o.Elements[k])
			if err != nil {
				return Undefined, err
			}
			t, terr := res.IsTrue()
			if terr != nil {
				return Undefined, terr
			}
			if t {
				return NewStringValue(k), nil
			}
		}
		return miss()
	}

	k, ok := needle.AsString()
	if !ok {
		return Undefined, errs.NewInvalidArgumentTypeError("index", "first", "a key or a predicate", needle.TypeName())
	}
	if _, exists := o.Elements[k]; exists {
		return NewStringValue(k), nil
	}
	return miss()
}
